from collections import deque

DIRECTIONS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def find(maze, ch):
    for r, row in enumerate(maze):
        if ch in row:
            return r, row.index(ch)
    return None


def shortest_steps(maze):
    rows, cols = len(maze), len(maze[0])
    sr, sc = find(maze, "S")
    queue = deque([(sr, sc, 0)])
    visited = {(sr, sc)}
    while queue:
        r, c, dist = queue.popleft()
        if maze[r][c] == "E":
            return dist
        for dr, dc in DIRECTIONS:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols):
                continue
            if maze[nr][nc] != "#" and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))
    return -1


open_maze = [
    "S.#.....",
    ".##.###.",
    "....#E..",
    ".##...#.",
]
walled_maze = [
    "S..#E",
    ".#.#.",
    "...##",
]
print("Open maze:", shortest_steps(open_maze))
print("Walled maze:", shortest_steps(walled_maze))

