from collections import deque


def shortest_path(graph, start, end):
    parent = {start: None}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node == end:
            break
        for nbr in graph[node]:
            if nbr not in parent:
                parent[nbr] = node
                queue.append(nbr)
    if end not in parent:
        return []
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = parent[node]
    path.reverse()
    return path


graph = {
    "A": ["B", "C"],
    "B": ["A", "D"],
    "C": ["A", "E", "F"],
    "D": ["B", "F"],
    "E": ["C"],
    "F": ["C", "D"],
    "G": [],
}
for end in ["F", "D", "G"]:
    path = shortest_path(graph, "A", end)
    print(" -> ".join(path) if path else "no path")

