from collections import deque


def shortest_path(graph, start, end):
    parent = {start: None}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node == end:
            break
        for nbr in sorted(graph.get(node, [])):
            if nbr not in parent:
                parent[nbr] = node
                queue.append(nbr)
    if end not in parent:
        return []
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = parent[node]
    path.reverse()
    return path


