from collections import deque

DIRECTIONS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def minutes_to_burn(grid):
    grid = [list(row) for row in grid]
    rows, cols = len(grid), len(grid[0])
    queue = deque()
    grass = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "*":
                queue.append((r, c))
            elif grid[r][c] == ".":
                grass += 1
    minutes = 0
    while queue:
        for _ in range(len(queue)):
            r, c = queue.popleft()
            for dr, dc in DIRECTIONS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == ".":
                    grid[nr][nc] = "*"
                    grass -= 1
                    queue.append((nr, nc))
        if queue:
            minutes += 1
    return minutes if grass == 0 else -1


field = [
    "*...#",
    "..#..",
    "#...*",
]
sealed = [
    "*.#..",
    "..#..",
]
print("Field:", minutes_to_burn(field))
print("Sealed:", minutes_to_burn(sealed))

